import java.util.*;
import java.nio.charset.StandardCharsets;
import org.joda.time.*;
import org.joda.time.format.*;

public class T2 {
  public static void main(String[] a) throws Exception {
    // --- base64url vs basic ---
    int basicFail=0, urlFail=0, agree=0, total=0;
    Random r = new Random(7);
    for(int i=0;i<4000;i++){
      byte[] b = new byte[30]; r.nextBytes(b);
      String enc = Base64.getUrlEncoder().withoutPadding().encodeToString(b);
      total++;
      byte[] viaUrl=null, viaBasic=null;
      try { viaUrl = Base64.getUrlDecoder().decode(enc); } catch(Exception e){ urlFail++; }
      try { viaBasic = Base64.getDecoder().decode(enc); } catch(Exception e){ basicFail++; }
      if(viaUrl!=null && viaBasic!=null && Arrays.equals(viaUrl,viaBasic)) agree++;
    }
    System.out.println("b64url payloads: total="+total+" basicDecoderFail="+basicFail+" urlDecoderFail="+urlFail+" agreeWhenBothOk="+agree);

    // a JSON payload example that yields '-' or '_' in base64url
    String json = "{\"consentId\":\"7f3a\",\"note\":\"\\u00fe\\u00ff>?\"}";
    String enc = Base64.getUrlEncoder().withoutPadding().encodeToString(json.getBytes(StandardCharsets.UTF_8));
    System.out.println("enc="+enc);
    try { System.out.println("basic -> "+new String(Base64.getDecoder().decode(enc),StandardCharsets.UTF_8)); }
    catch(Exception e){ System.out.println("basic -> EXCEPTION "+e); }
    System.out.println("url   -> "+new String(Base64.getUrlDecoder().decode(enc),StandardCharsets.UTF_8));

    // --- hh vs HH ---
    DateTimeFormatter bad = DateTimeFormat.forPattern("yyyy-MM-dd'T'hh:mm:ss.SSS'Z'");
    DateTimeFormatter good = DateTimeFormat.forPattern("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'");
    DateTime t = new DateTime(2024,3,11,13,47,22,123, DateTimeZone.UTC);
    System.out.println("13:47 bad="+t.toString(bad)+" good="+t.toString(good));
    DateTime m = new DateTime(2024,3,11,9,5,1,0, DateTimeZone.UTC);
    System.out.println("09:05 bad="+m.toString(bad)+" good="+m.toString(good));
    DateTime mid = new DateTime(2024,3,11,0,30,0,0, DateTimeZone.UTC);
    System.out.println("00:30 bad="+mid.toString(bad)+" good="+mid.toString(good));
    DateTime noon = new DateTime(2024,3,11,12,0,0,0, DateTimeZone.UTC);
    System.out.println("12:00 bad="+noon.toString(bad)+" good="+noon.toString(good));

    // round-trip through the app's own parser pattern
    java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'");
    sdf.setTimeZone(TimeZone.getTimeZone("UTC"));
    System.out.println("parse(bad 13:47) -> "+sdf.parse(t.toString(bad)).toInstant());
    System.out.println("parse(good 13:47) -> "+sdf.parse(t.toString(good)).toInstant());
  }
}
